<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api } from './api'

type Level = 'FREE' | 'ONE_BUSY' | 'MANY_BUSY'
type Cell = { dayOfWeek:number; slotCode:string; level:Level; busyCount:number; occupancies:{teacherName:string;courseName:string;occupancyText:string}[] }
type Result = { missingImport:boolean; cells:Cell[]; absentTeachers:string[]; semesterCode:string; week:number }
type Semester = { code:string; label:string; isCurrent:boolean }
type Teacher = { name:string; pinyinInitials:string }
type Preset = { name:string; teacherNames:string[] }
const semesters=ref<Semester[]>([]), semester=ref(''), week=ref(1), teacherQuery=ref(''), teacherHits=ref<Teacher[]>([]), selected=ref<string[]>([]), presets=ref<Preset[]>([])
const result=ref<Result|null>(null), filter=ref<Level|null>(null), selectedCell=ref<Cell|null>(null), cellDrawer=ref(false), picker=ref(false), missing=ref(false), error=ref('')
const username=ref(''), password=ref(''), syncBusy=ref(false), syncStatus=ref(''), syncProgress=ref<any>(null), slider=ref<any>(null), move=ref(0), programText=ref(''), importResult=ref<any>(null), colleges=ref<any[]>([])
let searchTimer:number|undefined, pollTimer:number|undefined
const slots=['0102','0304','0506','0708','0910','1112'], days=['周一','周二','周三','周四','周五','周六','周日']
const cells=computed(()=>result.value?.cells || []), visibleCells=computed(()=>filter.value ? cells.value.filter(c=>c.level===filter.value) : cells.value)
const count=(level:Level)=>cells.value.filter(c=>c.level===level).length
function cell(day:number,slot:string){return cells.value.find(c=>c.dayOfWeek===day&&c.slotCode===slot)}
function chooseCell(c:Cell){selectedCell.value=c;cellDrawer.value=true}
function addTeacher(t:Teacher){if(!selected.value.includes(t.name)) selected.value.push(t.name); teacherQuery.value='';teacherHits.value=[]}
function removeTeacher(name:string){selected.value=selected.value.filter(n=>n!==name)}
function search(){clearTimeout(searchTimer); if(!teacherQuery.value.trim()){teacherHits.value=[];return}; searchTimer=window.setTimeout(async()=>{try{const r:any=await api.get(`/api/teachers?q=${encodeURIComponent(teacherQuery.value)}&pageSize=8`);teacherHits.value=r.data||[]}catch(e:any){error.value=e.message}},180)}
async function query(){if(!semester.value||!selected.value.length){error.value='请选择学期和教师';return}try{error.value='';const r=await api.post<Result>('/api/common-free',{semesterCode:semester.value,week:Number(week.value),teacherNames:selected.value});result.value=r;missing.value=r.missingImport;filter.value=null}catch(e:any){error.value=e.message}}
function preset(p:Preset){selected.value=[...p.teacherNames];query()}
async function startSync(){if(!semester.value||syncBusy.value||slider.value)return;try{error.value='';syncBusy.value=true;syncStatus.value='启动同步…';const r:any=await api.post('/api/sync/start',{semesterCode:semester.value,username:username.value,password:password.value});if(r.status==='NEED_SLIDER')slider.value=r;else watchSync(r.jobId)}catch(e:any){error.value=e.message;syncBusy.value=false}}
async function submitSlider(){try{const r:any=await api.post('/api/sync/slider',{jobId:slider.value.jobId,canvasWidth:300,move:Number(move.value),tracks:[{a:Number(move.value),b:0,c:Date.now()}]});slider.value=null;watchSync(r.jobId)}catch(e:any){error.value=(e as Error).message}}
function watchSync(jobId:string){if(pollTimer!==undefined)clearInterval(pollTimer);syncStatus.value='同步进行中';const timer=window.setInterval(async()=>{try{const p:any=await api.get(`/api/sync/${jobId}`);if(pollTimer!==timer)return;syncProgress.value=p;if(p.status==='DONE'||p.status==='FAILED'){clearInterval(timer);pollTimer=undefined;syncBusy.value=false;syncStatus.value=p.status==='DONE'?'同步完成':'同步失败';if(p.status==='DONE')query()}}catch(e:any){if(pollTimer===timer)error.value=(e as Error).message}},800);pollTimer=timer}
async function importPrograms(){try{importResult.value=await api.post('/api/programs/import',{text:programText.value})}catch(e:any){error.value=(e as Error).message}}
function keydown(e:KeyboardEvent){if(e.key==='Escape'){cellDrawer.value=false;picker.value=false}if(!cellDrawer.value&&result.value&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter'].includes(e.key)){e.preventDefault();const current=selectedCell.value||cells.value[0];let d=current?.dayOfWeek||1,s=slots.indexOf(current?.slotCode||'0102');if(e.key==='ArrowUp')s=Math.max(0,s-1);if(e.key==='ArrowDown')s=Math.min(5,s+1);if(e.key==='ArrowLeft')d=Math.max(1,d-1);if(e.key==='ArrowRight')d=Math.min(7,d+1);const next=cell(d,slots[s]);if(e.key==='Enter'&&current)chooseCell(current);else if(next)selectedCell.value=next}}
onMounted(async()=>{window.addEventListener('keydown',keydown);try{semesters.value=await api.get('/api/semesters');semester.value=semesters.value.find(s=>s.isCurrent)?.code||semesters.value[0]?.code||'';const settings:any=await api.get('/api/settings');week.value=settings.currentWeek;presets.value=await api.get('/api/presets');colleges.value=await api.get('/api/colleges')}catch(e:any){error.value=e.message}})
onUnmounted(()=>{window.removeEventListener('keydown',keydown);clearInterval(pollTimer)})
</script>
<template><main>
<header class="top"><div class="brand"><span class="eyebrow">ACADEMIC AFFAIRS / LOCAL</span><h1>公共空闲 <i>工作台</i></h1></div><div class="top-actions"><button class="outline" @click="startSync">同步课表</button><button class="outline" @click="picker=true">批量导入</button></div></header>
<section class="omnibar panel"><div class="controls"><label>学期<select v-model="semester"><option v-for="s in semesters" :value="s.code">{{s.label}}</option></select></label><label>周次<input v-model.number="week" type="number" min="1" max="30"/></label><label class="search">教师 / 拼音首字母<input v-model="teacherQuery" @input="search" @keyup.enter="query" placeholder="输入姓名，回车查询"/><div v-if="teacherHits.length" class="hits"><button v-for="t in teacherHits" @click="addTeacher(t)">{{t.name}} <small>{{t.pinyinInitials}}</small></button></div></label><button class="primary" @click="query">查询 ↵</button></div><div class="chips"><span v-for="n in selected" class="chip selected">{{n}} <button @click="removeTeacher(n)">×</button></span><span v-for="p in presets" class="chip preset" @click="preset(p)">▸ {{p.name}}</span></div></section>
<section class="sync panel"><div><strong>同步课表</strong><span>{{syncStatus||'按需从教务拉取最新课表'}}</span></div><label class="sync-input">账号<input v-model="username" autocomplete="username" placeholder="可留空，使用服务端配置"/></label><label class="sync-input">密码<input v-model="password" type="password" autocomplete="current-password" placeholder="仅保存在当前页面"/></label><div v-if="syncProgress" class="progress"><b>{{syncProgress.currentCollege||'准备中'}}</b><span>{{syncProgress.finishedColleges}} / {{syncProgress.totalColleges}} 个学院</span></div><div v-if="slider" class="slider"><p>教务需要人工滑块校验（不自动破解）</p><img :src="`data:image/png;base64,${slider.backgroundBase64}`"/><img :src="`data:image/png;base64,${slider.pieceBase64}`"/><label>拖动距离 <input v-model.number="move" type="number"/><button class="primary" @click="submitSlider">提交</button></label></div></section>
<div v-if="error" class="notice error">{{error}}</div><section class="filters"><button :class="{active:filter===null}" @click="filter=null">全部 <b>{{cells.length}}</b></button><button :class="{free:filter==='FREE'}" @click="filter='FREE'">全员空闲 <b>{{count('FREE')}}</b></button><button :class="{one:filter==='ONE_BUSY'}" @click="filter='ONE_BUSY'">仅 1 人忙碌 <b>{{count('ONE_BUSY')}}</b></button><button :class="{many:filter==='MANY_BUSY'}" @click="filter='MANY_BUSY'">多人冲突 <b>{{count('MANY_BUSY')}}</b></button></section>
<section v-if="result&&!missing" class="matrix panel"><div class="corner">节次 / 星期</div><div v-for="d in days" class="day">{{d}}</div><template v-for="s in slots"><div class="slot">{{s}}</div><button v-for="d in [1,2,3,4,5,6,7]" :class="['cell',cell(d,s)?.level.toLowerCase(),{dim:filter&&cell(d,s)?.level!==filter,focus:selectedCell===cell(d,s)}]" @click="cell(d,s)&&chooseCell(cell(d,s)!)"><span>{{cell(d,s)?.busyCount||0}}</span><small>{{cell(d,s)?.level==='FREE'?'空闲':cell(d,s)?.level==='ONE_BUSY'?'1 人忙':'多人'}}</small></button></template></section>
<div v-else-if="!result" class="empty panel">选择教师并回车查询，42 个时间格会在这里展开。</div>
<aside v-if="cellDrawer" class="drawer"><button class="close" @click="cellDrawer=false">×</button><span class="eyebrow">CELL DETAIL</span><h2>{{days[(selectedCell?.dayOfWeek||1)-1]}} · {{selectedCell?.slotCode}}</h2><p class="level">{{selectedCell?.busyCount}} 人忙碌</p><h3>有课教师</h3><p v-for="o in selectedCell?.occupancies" class="occupancy"><b>{{o.teacherName}}</b><span>{{o.courseName}}</span></p><h3>原始占用文本</h3><pre>{{selectedCell?.occupancies.map(o=>o.occupancyText).join('\n')||'无占用'}}</pre><button class="outline" @click="navigator.clipboard.writeText(selectedCell?.occupancies.map(o=>o.occupancyText).join('\n')||'')">复制原文</button></aside>
<div v-if="missing" class="modal"><div class="dialog"><span class="eyebrow">NO IMPORT</span><h2>这个学期还没有课表</h2><p>先同步 {{semester}}，再查看公共空闲。</p><button class="primary" @click="missing=false;startSync()">同步 {{semester}}</button></div></div>
<aside v-if="picker" class="drawer picker"><button class="close" @click="picker=false">×</button><span class="eyebrow">IMPORT</span><h2>批量专业归档</h2><p class="muted">按“姓名,学院,专业”每行粘贴；这是辅助路径。</p><h3>学院</h3><div class="college-list"><span v-for="c in colleges">{{c.name}}</span></div><label>粘贴内容<textarea v-model="programText" rows="9" placeholder="张三,智能制造学院,软件技术"></textarea></label><button class="primary" @click="importPrograms">匹配并保存</button><div v-if="importResult" class="notice">匹配 {{importResult.matched}} 条；未匹配：{{importResult.unmatchedNames.join('、')||'无'}}</div></aside>
</main></template>
